const inner=new THREE.PointLight(0xffffff,.7,8,1.4);inner.position.set(0,4.3,1.1);S.add(inner);
// materials
const mat=(c,o={})=>new THREE.MeshPhysicalMaterial(Object.assign({color:c,roughness:.42,clearcoat:.55,clearcoatRoughness:.22,envMapIntensity:.45},o));
const blue=mat(0x1e8fe6), blueD=mat(0x1170c4), cream=mat(0xe2f4fe,{roughness:.35}), knobM=mat(0x3aa6ec,{roughness:.25,clearcoat:.9});
